package edu.lablink; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.UUID; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; public JwtService(@Value("${JWT_SECRET:}") String secret){ if(secret.length()<32) throw new IllegalStateException("Set JWT_SECRET to at least 32 characters"); key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); } public String issue(UserEntity u){return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole()).issuedAt(new java.util.Date()).expiration(java.util.Date.from(Instant.now().plus(Duration.ofHours(8)))).signWith(key).compact();} public UUID subject(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());}}
